const sites = $input.first().json.siteEntry || [];

return sites.map(site => ({
  json: {
    siteUrl: site.siteUrl,
    permissionLevel: site.permissionLevel
  }
}));

const responses = $input.all();
const sites = $('Split Search Console Sites').all();

return responses.map((item, index) => {

  const response = item.json || {};
  const site = sites[index]?.json || {};

  const siteUrl = site.siteUrl || '';

  const domain = siteUrl
    .replace('sc-domain:', '')
    .replace(/^https?:\/\//, '')
    .replace(/\/$/, '');

  const row =
    Array.isArray(response.rows) && response.rows.length > 0
      ? response.rows[0]
      : null;

  const date =
    row?.keys?.[0] ||
    $now.minus({ days: 3 }).toFormat('yyyy-MM-dd');

  const clicks = Number(row?.clicks ?? 0);
  const impressions = Number(row?.impressions ?? 0);
  const ctrRaw = Number(row?.ctr ?? 0);
  const positionRaw = Number(row?.position ?? 0);

  return {
    json: {
      date: date,
      website: siteUrl,
      domain: domain,
      permissionLevel: site.permissionLevel || '',
      clicks: clicks,
      impressions: impressions,
      ctrPercent: Number((ctrRaw * 100).toFixed(2)),
      averagePosition:
        impressions > 0
          ? Number(positionRaw.toFixed(2))
          : null,
      dataStatus:
        impressions > 0
          ? 'Has Data'
          : 'No Search Data',

      recordKey: `${date}|${domain}`
    }
  };

});

const responses = $input.all();
const sites = $('Split Search Console Sites').all();

const output = [];

for (let i = 0; i < responses.length; i++) {

  const response = responses[i]?.json || {};
  const site = sites[i]?.json || {};

  const siteUrl = site.siteUrl || '';

  const domain = siteUrl
    .replace('sc-domain:', '')
    .replace(/^https?:\/\//, '')
    .replace(/\/$/, '');

  const rows = Array.isArray(response.rows)
    ? response.rows
    : [];

  for (const row of rows) {

    const date = row?.keys?.[0] || '';
    const pageUrl = row?.keys?.[1] || '';

    const clicks = Number(row?.clicks ?? 0);
    const impressions = Number(row?.impressions ?? 0);
    const ctrRaw = Number(row?.ctr ?? 0);
    const positionRaw = Number(row?.position ?? 0);

    let pagePath = '/';

    try {
      pagePath = new URL(pageUrl).pathname || '/';
    } catch (error) {
      pagePath = pageUrl
        .replace(/^https?:\/\/[^/]+/i, '') || '/';
    }

    const recordKey =
      `${date}|${domain}|${encodeURIComponent(pageUrl)}`;

    output.push({
      json: {
        date: date,
        website: siteUrl,
        domain: domain,
        pageUrl: pageUrl,
        pagePath: pagePath,
        clicks: clicks,
        impressions: impressions,
        ctrPercent: Number((ctrRaw * 100).toFixed(2)),
        averagePosition: impressions > 0
          ? Number(positionRaw.toFixed(2))
          : null,
        dataStatus: impressions > 0
          ? 'Has Data'
          : 'No Search Data',
        recordKey: recordKey
      }
    });
  }
}

return output;

