const items = $input.all().map(item => item.json);

// Search Console reporting date
const reportDate = items[0]?.date || '';

// Actual date the workflow/report runs
const generatedDate = $now.toFormat('dd/MM/yyyy');

const totalWebsites = items.length;

const sitesWithData = items.filter(
  x => Number(x.impressions || 0) > 0
).length;

const noSearchData = totalWebsites - sitesWithData;

const totalClicks = items.reduce(
  (sum, x) => sum + Number(x.clicks || 0),
  0
);

const totalImpressions = items.reduce(
  (sum, x) => sum + Number(x.impressions || 0),
  0
);

const overallCtr = totalImpressions > 0
  ? Number(((totalClicks / totalImpressions) * 100).toFixed(2))
  : 0;

// Weighted average position
const positionItems = items.filter(
  x =>
    Number(x.impressions || 0) > 0 &&
    x.averagePosition !== null &&
    x.averagePosition !== ''
);

const weightedPositionTotal = positionItems.reduce(
  (sum, x) =>
    sum +
    Number(x.averagePosition || 0) *
    Number(x.impressions || 0),
  0
);

const weightedImpressions = positionItems.reduce(
  (sum, x) => sum + Number(x.impressions || 0),
  0
);

const overallAveragePosition = weightedImpressions > 0
  ? Number(
      (weightedPositionTotal / weightedImpressions).toFixed(2)
    )
  : null;

// Top 10 websites
const topSites = [...items]
  .filter(x => Number(x.impressions || 0) > 0)
  .sort((a, b) => {
    if (Number(b.clicks || 0) !== Number(a.clicks || 0)) {
      return Number(b.clicks || 0) - Number(a.clicks || 0);
    }

    return Number(b.impressions || 0) - Number(a.impressions || 0);
  })
  .slice(0, 10);

// Top 10 sites needing ranking attention
const attentionSites = [...items]
  .filter(
    x =>
      Number(x.impressions || 0) > 0 &&
      Number(x.averagePosition || 0) > 30
  )
  .sort(
    (a, b) =>
      Number(b.impressions || 0) -
      Number(a.impressions || 0)
  )
  .slice(0, 10);

// Top sites text
const topSitesText = topSites.length
  ? topSites
      .map(
        (x, i) =>
          `${i + 1}. ${x.domain} — ${x.clicks} clicks, ${x.impressions} impressions, ${x.ctrPercent}% CTR, Pos. ${x.averagePosition ?? '-'}`
      )
      .join('\n')
  : 'No sites with search data.';

// Ranking attention text
const attentionText = attentionSites.length
  ? attentionSites
      .map(
        (x, i) =>
          `${i + 1}. ${x.domain} — ${x.impressions} impressions, Avg Pos. ${x.averagePosition}`
      )
      .join('\n')
  : 'No high-impression sites currently ranking below position 30.';

// Slack message
const slackMessage =
`📊 *Zenith Website SEO Daily Report*

📅 *Report Generated:* ${generatedDate}
🔎 *Search Console Data Date:* ${reportDate}

*Portfolio Overview*
• Websites Monitored: ${totalWebsites}
• Websites With Search Data: ${sitesWithData}
• No Search Data: ${noSearchData}
• Total Clicks: ${totalClicks}
• Total Impressions: ${totalImpressions}
• Overall CTR: ${overallCtr}%
• Weighted Avg Position: ${overallAveragePosition ?? '-'}

🏆 *Top 10 Websites*
${topSitesText}

⚠️ *Top 10 Ranking Attention*
${attentionText}

📈 Full daily, weekly, 28-day, page and keyword data is available in the Zenith Website Views Monitoring dashboard.`;

return [
  {
    json: {
      generatedDate,
      reportDate,
      totalWebsites,
      sitesWithData,
      noSearchData,
      totalClicks,
      totalImpressions,
      overallCtr,
      overallAveragePosition,
      slackMessage
    }
  }
];

const sites = $input.first().json.siteEntry || [];

return sites
  .filter(site => site.permissionLevel !== 'siteUnverifiedUser')
  .map(site => ({
    json: {
      siteUrl: site.siteUrl,
      permissionLevel: site.permissionLevel
    }
  }));

