const items = $input.all().map(item => item.json);

const unique = new Map();

for (const item of items) {

  const key =
    item.recordKey ||
    `${item.date || ''}|${item.domain || ''}`;

  if (!key) continue;

  const existing = unique.get(key);

  // If the same domain exists in both Google accounts,
  // keep the record containing the stronger Search Console data.
  if (!existing) {
    unique.set(key, item);
    continue;
  }

  const existingImpressions = Number(existing.impressions || 0);
  const currentImpressions = Number(item.impressions || 0);

  const existingClicks = Number(existing.clicks || 0);
  const currentClicks = Number(item.clicks || 0);

  if (
    currentImpressions > existingImpressions ||
    (
      currentImpressions === existingImpressions &&
      currentClicks > existingClicks
    )
  ) {
    unique.set(key, item);
  }
}

return Array.from(unique.values()).map(item => ({
  json: item
}));

