const items = $input.all().map(item => item.json);

// Preferred GA4 properties for domains that have duplicates.
const preferredProperties = {
  'site-one.example.com': 'REPLACE_WITH_GA4_PROPERTY_1',
  'site-two.example.com': 'REPLACE_WITH_GA4_PROPERTY_2',
  'site-three.example.com': 'REPLACE_WITH_GA4_PROPERTY_3'
};

const grouped = new Map();

for (const item of items) {

  const domain = String(item.domain || '')
    .toLowerCase()
    .replace(/^www\./, '');

  if (!domain) continue;

  if (!grouped.has(domain)) {
    grouped.set(domain, []);
  }

  grouped.get(domain).push(item);
}

const output = [];

for (const [domain, properties] of grouped.entries()) {

  const preferredId = preferredProperties[domain];

  let selected = null;
  let propertySelection = '';

  // Use manually preferred property when it exists.
  if (preferredId) {
    selected = properties.find(
      p => String(p.propertyId) === String(preferredId)
    );

    if (selected) {
      propertySelection = 'Preferred Property';
    }
  }

  // If only one property exists, use it automatically.
  if (!selected && properties.length === 1) {
    selected = properties[0];
    propertySelection = 'Single Property';
  }

  // Multiple properties but preferred property unavailable.
  if (!selected) {
    selected = [...properties].sort((a, b) =>
      String(a.propertyId).localeCompare(
        String(b.propertyId),
        undefined,
        { numeric: true }
      )
    )[0];

    propertySelection = 'Automatic Fallback';
  }

  output.push({
    json: {
      ...selected,
      duplicatePropertyCount: properties.length,
      propertySelection
    }
  });
}

return output;

