};

const pad = (value, length, right = false) => {
  let text = String(value ?? '');

  if (text.length > length) {
    text = text.substring(0, length);
  }

  return right
    ? text.padStart(length)
    : text.padEnd(length);
};


// ======================================================
// 3. DATES
// ======================================================

const generatedDate =
  seo.generatedDate ||
  ga4.generatedDate ||
  $now.toFormat('dd/MM/yyyy');

const generatedTime =
  ga4.generatedTime ||
  $now.toFormat('hh:mm a');

const searchDate =
  seo.reportDate || 'N/A';

const analyticsDate =
  ga4.reportDate || 'N/A';


// ======================================================
// 4. SEARCH CONSOLE KPI
// ======================================================

const searchWebsites = num(seo.totalWebsites);
const searchWithData = num(seo.sitesWithData);
const noSearchData = num(seo.noSearchData);

const totalClicks = num(seo.totalClicks);
const totalImpressions = num(seo.totalImpressions);

const overallCtr = num(seo.overallCtr);

const averagePosition = num(
  seo.overallAveragePosition ??
  seo.weightedPosition
);

const searchCoverage =
  searchWebsites > 0
    ? (searchWithData / searchWebsites) * 100
    : 0;


// ======================================================
// 5. GA4 KPI
// ======================================================

const ga4Websites = num(ga4.totalWebsites);
const ga4WithData = num(ga4.sitesWithData);
const noAnalyticsData = num(ga4.noAnalyticsData);

const totalViews = num(ga4.totalViews);
const totalVisitors = num(ga4.totalVisitors);
const totalSessions = num(ga4.totalSessions);
const totalNewUsers = num(ga4.totalNewUsers);
const totalEngagedSessions = num(ga4.totalEngagedSessions);

const analyticsCoverage =
  ga4Websites > 0
    ? (ga4WithData / ga4Websites) * 100
    : 0;

const engagementRate =
  totalSessions > 0
    ? (totalEngagedSessions / totalSessions) * 100
    : 0;


// ======================================================
// 6. EXTRACT SEARCH TOP WEBSITES
// ======================================================

let searchWebsitesData = [];

if (Array.isArray(seo.topWebsites)) {

  searchWebsitesData = seo.topWebsites.map(x => ({
    domain: normalizeDomain(
      x.domain ||
      x.website ||
      x.site
    ),

    clicks: num(x.clicks),

    impressions: num(x.impressions),

    ctr: num(
      x.ctr ??
      x.ctrPercent
    ),

    position: num(
      x.averagePosition ??
      x.position
    )
  }));

} else {

  const seoText = String(
    seo.slackMessage ||
    seo.message ||
    ''
  );

  const lines = seoText.split('\n');

  for (const line of lines) {

    const match = line.match(
      /^\s*\d+\.\s+(.+?)\s+[—-]\s+([\d,]+)\s+clicks?,\s+([\d,]+)\s+impressions?,\s+([\d.]+)%\s+CTR,\s+Pos\.\s+([\d.]+)/i
    );

    if (!match) continue;

    searchWebsitesData.push({
      domain: normalizeDomain(match[1]),
      clicks: num(match[2].replace(/,/g, '')),
      impressions: num(match[3].replace(/,/g, '')),
      ctr: num(match[4]),
      position: num(match[5])
    });
  }
}


// Remove duplicates
const searchMap = new Map();

for (const item of searchWebsitesData) {

  if (!item.domain) continue;

  if (!searchMap.has(item.domain)) {
    searchMap.set(item.domain, item);
  }
}

searchWebsitesData = [...searchMap.values()];


// ======================================================
// 7. EXTRACT GA4 TOP WEBSITES
// ======================================================

let trafficWebsitesData = [];

if (Array.isArray(ga4.topWebsites)) {

  trafficWebsitesData = ga4.topWebsites.map(x => ({
    domain: normalizeDomain(
      x.domain ||
      x.website
    ),

    views: num(x.views),
    visitors: num(x.visitors),
    sessions: num(x.sessions),
    newUsers: num(x.newUsers)
  }));

} else {

  const ga4Text = String(
    ga4.slackMessage ||
    ga4.message ||
    ''
  );

  const lines = ga4Text
    .split('\n')
    .map(x => x.trim());

  for (let i = 0; i < lines.length; i++) {

    const siteMatch = lines[i].match(
      /^\d+\.\s+(.+)$/i
    );

    if (!siteMatch) continue;

    const possibleDomain =
      normalizeDomain(siteMatch[1]);

    if (!possibleDomain.includes('.')) {
      continue;
    }

    let views = 0;
    let visitors = 0;
    let sessions = 0;

    for (
      let j = i + 1;
      j <= Math.min(i + 4, lines.length - 1);
      j++
    ) {

      const viewMatch =
        lines[j].match(/^Views:\s*([\d,]+)/i);

      const visitorMatch =
        lines[j].match(/^Visitors:\s*([\d,]+)/i);

      const sessionMatch =
        lines[j].match(/^Sessions:\s*([\d,]+)/i);

      if (viewMatch) {
        views = num(
          viewMatch[1].replace(/,/g, '')
        );
      }

      if (visitorMatch) {
        visitors = num(
          visitorMatch[1].replace(/,/g, '')
        );
      }

      if (sessionMatch) {
        sessions = num(
          sessionMatch[1].replace(/,/g, '')
        );
      }
    }

    if (
      views > 0 ||
      visitors > 0 ||
      sessions > 0
    ) {

      trafficWebsitesData.push({
        domain: possibleDomain,
        views,
        visitors,
        sessions,
        newUsers: 0
      });
    }
  }
}


// Remove duplicate GA4 domains
const trafficMap = new Map();

for (const item of trafficWebsitesData) {

  if (!item.domain) continue;

  const current = trafficMap.get(item.domain);

  if (
    !current ||
    item.views > current.views
  ) {
    trafficMap.set(item.domain, item);
  }
}

trafficWebsitesData =
  [...trafficMap.values()];


// ======================================================
// 8. TOP SEARCH PERFORMANCE
// ======================================================

const topSearch = [...searchWebsitesData]
  .sort((a, b) => {

    if (b.clicks !== a.clicks) {
      return b.clicks - a.clicks;
    }

    return b.impressions - a.impressions;
  })
  .slice(0, 5);


// ======================================================
// 9. TOP GA4 TRAFFIC
// ======================================================

const topTraffic = [...trafficWebsitesData]
  .filter(x =>
    x.views > 0 ||
    x.visitors > 0 ||
    x.sessions > 0
  )
  .sort((a, b) => {

    if (b.views !== a.views) {
      return b.views - a.views;
    }

    if (b.visitors !== a.visitors) {
      return b.visitors - a.visitors;
    }

    return b.sessions - a.sessions;
  })
  .slice(0, 5);


// ======================================================
// 10. BUILD COMBINED WEBSITE MAP
// ======================================================

const combinedMap = new Map();

for (const site of searchWebsitesData) {

  combinedMap.set(site.domain, {
    domain: site.domain,

    clicks: site.clicks,
    impressions: site.impressions,
    ctr: site.ctr,
    position: site.position,

    views: 0,
    visitors: 0,
    sessions: 0
  });
}

for (const site of trafficWebsitesData) {

  const existing =
    combinedMap.get(site.domain) || {
      domain: site.domain,

      clicks: 0,
      impressions: 0,
      ctr: 0,
      position: 0,

      views: 0,
      visitors: 0,
      sessions: 0
    };

  existing.views = site.views;
  existing.visitors = site.visitors;
  existing.sessions = site.sessions;

  combinedMap.set(
    site.domain,
    existing
  );
}


// ======================================================
// 11. TOP COMBINED PERFORMANCE
// ======================================================

const combinedWebsites =
  [...combinedMap.values()]
    .sort((a, b) => {

      // Prioritize meaningful performance
      const scoreA =
        (a.clicks * 100000) +
        (a.views * 1000) +
        a.impressions;

      const scoreB =
        (b.clicks * 100000) +
        (b.views * 1000) +
        b.impressions;

      return scoreB - scoreA;
    })
    .slice(0, 10);


// ======================================================
// 12. COMBINED TABLE
// ======================================================

const header =
  `${pad('Website', 28)} ` +
  `${pad('Clk', 4, true)} ` +
  `${pad('Impr', 6, true)} ` +
  `${pad('View', 5, true)} ` +
  `${pad('User', 5, true)}`;

const separator =
  `${'-'.repeat(28)} ` +
  `${'-'.repeat(4)} ` +
  `${'-'.repeat(6)} ` +
  `${'-'.repeat(5)} ` +
  `${'-'.repeat(5)}`;

const rows = combinedWebsites.map(site =>

  `${pad(shortDomain(site.domain, 28), 28)} ` +
  `${pad(fmt(site.clicks), 4, true)} ` +
  `${pad(fmt(site.impressions), 6, true)} ` +
  `${pad(fmt(site.views), 5, true)} ` +
  `${pad(fmt(site.visitors), 5, true)}`

).join('\n');

const combinedTable =
`${header}
${separator}
${rows || 'No website performance data'}`;


// ======================================================
// 13. TOP SEARCH TEXT
// ======================================================

const topSearchText =
  topSearch.length > 0

    ? topSearch.map((site, index) =>

        `*${index + 1}. ${site.domain}*\n` +
        `🔗 ${fmt(site.clicks)} clicks  •  ` +
        `👁 ${fmt(site.impressions)} impressions\n` +
        `CTR ${dec(site.ctr)}%  •  ` +
        `Avg Position ${dec(site.position)}`

      ).join('\n\n')

    : 'No Search Console performance data available.';


// ======================================================
// 14. TOP TRAFFIC TEXT
// ======================================================

const topTrafficText =
  topTraffic.length > 0

    ? topTraffic.map((site, index) =>

        `*${index + 1}. ${site.domain}*\n` +
        `👁 ${fmt(site.views)} views  •  ` +
        `👥 ${fmt(site.visitors)} visitors  •  ` +
        `🔄 ${fmt(site.sessions)} sessions`

      ).join('\n\n')

    : 'No GA4 website traffic recorded for this period.';


// ======================================================
// 15. RANKING ATTENTION
// ======================================================

let rankingAttention = [];

const seoText = String(
  seo.slackMessage ||
  seo.message ||
  ''
);

for (const line of seoText.split('\n')) {

  const match = line.match(
    /^\s*\d+\.\s+(.+?)\s+[—-]\s+([\d,]+)\s+impressions?,\s+Avg\s+Pos\.?\s+([\d.]+)/i
  );

  if (!match) continue;

  rankingAttention.push({
    domain: normalizeDomain(match[1]),

    impressions:
      num(match[2].replace(/,/g, '')),

    position:
      num(match[3])
  });
}


// fallback
if (!rankingAttention.length) {

  rankingAttention =
    searchWebsitesData
      .filter(x => x.position >= 30)
      .map(x => ({
        domain: x.domain,
        impressions: x.impressions,
        position: x.position
      }));
}

rankingAttention =
  rankingAttention
    .sort((a, b) =>
      b.impressions - a.impressions
    )
    .slice(0, 5);

const attentionText =
  rankingAttention.length

    ? rankingAttention.map((site, index) => {

        const icon =
          site.position >= 60
            ? '🔴'
            : site.position >= 40
              ? '🟠'
              : '🟡';

        return (
          `${icon} *${index + 1}. ${site.domain}*\n` +
          `${fmt(site.impressions)} impressions  •  ` +
          `Avg Position ${dec(site.position)}`
        );

      }).join('\n\n')

    : '🟢 No major ranking issues detected.';


// ======================================================
// 16. MANAGEMENT INSIGHTS
// ======================================================

const bestSearch =
  topSearch[0] || null;

const bestTraffic =
  topTraffic[0] || null;

let managementInsights = '';

if (bestSearch) {

  managementInsights +=
    `🏆 *Best Search Performer:* ` +
    `${bestSearch.domain} — ` +
    `${fmt(bestSearch.clicks)} clicks\n`;
}

if (bestTraffic) {

  managementInsights +=
    `👥 *Highest Traffic:* ` +
    `${bestTraffic.domain} — ` +
    `${fmt(bestTraffic.views)} views\n`;
}

managementInsights +=
  `🔎 *Search Coverage:* ${searchCoverage.toFixed(1)}%\n` +
  `📊 *GA4 Coverage:* ${analyticsCoverage.toFixed(1)}%\n` +
  `📈 *Portfolio CTR:* ${dec(overallCtr)}%\n` +
  `📍 *Average Google Position:* ${dec(averagePosition)}`;

if (totalSessions > 0) {

  managementInsights +=
    `\n⚡ *Engaged Session Rate:* ` +
    `${engagementRate.toFixed(1)}%`;
}


// ======================================================
// 17. SLACK BLOCK KIT DASHBOARD
// ======================================================

const blocks = [

  // HEADER
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: '📊 ZENITH WEBSITE PERFORMANCE DASHBOARD',
      emoji: true
    }
  },

  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text:
          `📅 *${generatedDate} ${generatedTime}*  |  ` +
          `🔎 Search: *${searchDate}*  |  ` +
          `📈 Traffic: *${analyticsDate}*`
      }
    ]
  },

  {
    type: 'divider'
  },


  // PORTFOLIO HEALTH
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*🌐 PORTFOLIO HEALTH*'
    }
  },

  {
    type: 'section',
    fields: [

      {
        type: 'mrkdwn',
        text:
          `*🔎 Search Visibility*\n` +
          `🟢 *${fmt(searchWithData)} / ${fmt(searchWebsites)}* websites\n` +
          `*${searchCoverage.toFixed(1)}% coverage*`
      },

      {
        type: 'mrkdwn',
        text:
          `*📊 Analytics Coverage*\n` +
          `🟢 *${fmt(ga4WithData)} / ${fmt(ga4Websites)}* websites\n` +
          `*${analyticsCoverage.toFixed(1)}% coverage*`
      },

      {
        type: 'mrkdwn',
        text:
          `*⚠️ No Search Data*\n` +
          `${fmt(noSearchData)} websites`
      },

      {
        type: 'mrkdwn',
        text:
          `*⚠️ No GA4 Data*\n` +
          `${fmt(noAnalyticsData)} websites`
      }
    ]
  },

  {
    type: 'divider'
  },


  // KPI
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*📈 EXECUTIVE KPI SNAPSHOT*'
    }
  },

  {
    type: 'section',
    fields: [

      {
        type: 'mrkdwn',
        text:
          `*🔎 GOOGLE SEARCH*\n\n` +
          `*${fmt(totalClicks)}* Clicks\n` +
          `*${fmt(totalImpressions)}* Impressions\n` +
          `*${dec(overallCtr)}%* CTR\n` +
          `*${dec(averagePosition)}* Avg Position`
      },

      {
        type: 'mrkdwn',
        text:
          `*👥 WEBSITE TRAFFIC*\n\n` +
          `*${fmt(totalViews)}* Views\n` +
          `*${fmt(totalVisitors)}* Visitors\n` +
          `*${fmt(totalSessions)}* Sessions\n` +
          `*${fmt(totalNewUsers)}* New Users`
      }
    ]
  },

  {
    type: 'divider'
  },


  // COMBINED TABLE
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text:
        '*🏆 COMBINED WEBSITE PERFORMANCE*\n' +
        'Search Console + Google Analytics 4'
    }
  },

  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text:
        '```' +
        combinedTable +
        '```'
    }
  },

  {
    type: 'divider'
  },


  // TWO LEADERBOARDS
  {
    type: 'section',
    fields: [

      {
        type: 'mrkdwn',
        text:
          `*🔎 TOP SEARCH PERFORMANCE*\n\n` +
          topSearchText
      },

      {
        type: 'mrkdwn',
        text:
          `*📈 TOP GA4 TRAFFIC*\n\n` +
          topTrafficText
      }
    ]
  },

  {
    type: 'divider'
  },


  // ATTENTION
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text:
        `*⚠️ RANKING ATTENTION*\n\n` +
        attentionText
    }
  },

  {
    type: 'divider'
  },


  // MANAGEMENT
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text:
        `*💡 MANAGEMENT INSIGHTS*\n\n` +
        managementInsights
    }
  },

  {
    type: 'divider'
  },

  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text:
          '✅ *Zenith automated Search Console + GA4 monitoring completed successfully.*'
      }
    ]
  }
];


// ======================================================
// 18. FALLBACK TEXT
// ======================================================

const message =
`📊 ZENITH WEBSITE PERFORMANCE DASHBOARD

🔎 Search: ${searchDate}
📈 Traffic: ${analyticsDate}

Search
Clicks: ${fmt(totalClicks)}
Impressions: ${fmt(totalImpressions)}
CTR: ${dec(overallCtr)}%
Avg Position: ${dec(averagePosition)}

Traffic
Views: ${fmt(totalViews)}
Visitors: ${fmt(totalVisitors)}
Sessions: ${fmt(totalSessions)}
New Users: ${fmt(totalNewUsers)}`;


// ======================================================
// 19. OUTPUT
// ======================================================

return [
  {
    json: {
      message,
      blocks
    }
  }
];

parameters.jsonBody:
={{ JSON.stringify({
  channel: "REPLACE_WITH_SLACK_DESTINATION_1",
  text: $json.message,
  blocks: $json.blocks,
  unfurl_links: false,
  unfurl_media: false
}) }}

parameters.jsCode:
const responses = $input.all();
const properties = $('Select Preferred GA4 Properties').all();

const output = [];

for (let i = 0; i < responses.length; i++) {

  const response = responses[i]?.json || {};
  const source = properties[i]?.json || {};

  const row =
    Array.isArray(response.rows) && response.rows.length > 0
      ? response.rows[0]
      : null;

  const values =
    row && Array.isArray(row.metricValues)
      ? row.metricValues
      : [];

  const activeUsers =
    Number(values[0]?.value || 0);

  const pageViews =
    Number(values[1]?.value || 0);

  output.push({
    json: {
      domain: source.domain || '',
      website: source.website || '',
      propertyId: source.propertyId || '',
      measurementId: source.measurementId || '',

      activeUsers,
      pageViews,

      realtimeStatus:
        activeUsers > 0 || pageViews > 0
          ? 'GA4 Realtime Working'
          : 'No Realtime Data'
    }
  });
}

return output;
